sys_ws_operation.operation_script:
(function process(request, response) {
    const ITEMS_PER_PAGE = 10;
    const portfolioIds = [];
    var logger = ['GetProjectTaskChronology', request.body.data.page, JSON.stringify(request.body.data.query)];
    let portfolioCount = 0;
    let programCount = 0;
    let projectCount = 0;
    let projectIds = [];
    // Column configuration data
    const COLUMN_DATA = [{
            "label": "Name",
            "name": "text",
            "type": "text",
            "resize": true,
            "hidden": false,
            "hideable": false,
            "cellContextMenu": false,
            "isClickable": true,
            "editable": true,
            "internalColumnName": {
                "pm_portfolio": "name",
                "pm_program": "short_description",
                "pm_project": "short_description",
                "pm_project_task": "short_description"
            }
        },
        {
            "label": "Mangager",
            "name": "owner",
            "editable": false,
            "type": "reference",
            "width": 130,
            "hideable": true,
            "hidden": false,
            "cellContextMenu": false,
            "referenceTable": "sys_user",
            "dbColumnName": "assigned_to",
            "internalColumnName": {
                "pm_portfolio": "portfolio_manager",
                "pm_program": "program_manager",
                "pm_project": "project_manager",
                "pm_project_task": "assigned_to"
            }
        },
        {
            "label": "Description",
            "name": "description",
            "type": "text",
            "resize": true,
            "hidden": true,
            "hideable": true,
            "cellContextMenu": false,
            "editable": true,
            "internalColumnName": {
                "pm_portfolio": "description",
                "pm_program": "description",
                "pm_project": "description",
                "pm_project_task": "description"
            }
        },
        {
            "label": "Assigned to",
            "name": "assigned_to",
            "type": "avatar",
            "width": 250,
            "hidden": false,
            "hideable": true,
            "cellContextMenu": false,
            "editable": true,
            "referenceTable": "sys_user",
            "dbColumnName": "assigned_to",
            "internalColumnName": {
                "pm_project_task": "assigned_to"
            }
        },
        {
            "label": "Start Date",
            "name": "startDate",
            "type": "date",
            "hidden": false,
            "editable": true,
            "hideTime": true,
            "cellContextMenu": false,
            "internalColumnName": {
                "pm_program": "start_date",
                "pm_project": "start_date",
                "pm_project_task": "start_date"
            }
        },
        {
            "label": "End Date",
            "name": "endDate",
            "type": "date",
            "hidden": false,
            "editable": true,
            "hideTime": true,
            "cellContextMenu": false,
            "internalColumnName": {
                "pm_program": "end_date",
                "pm_project": "end_date",
                "pm_project_task": "end_date"
            }
        },
        {
            "label": "Planned Duration(Days)",
            "name": "duration",
            "type": "string",
            "hidden": false,
            "editable": true,
            "cellContextMenu": false,
            "internalColumnName": {
                "pm_project_task": "duration"
            }
        },
        {
            "label": "State",
            "name": "state",
            "editable": true,
            "type": "string",
            "width": 130,
            "hideable": false,
            "cellContextMenu": false,
            "isChoice": true,
            "choices": [{
                    "value": "-5",
                    "displayValue": "Pending"
                },
                {
                    "value": "1",
                    "displayValue": "Open"
                },
                {
                    "value": "2",
                    "displayValue": "Work in Progress"
                },
                {
                    "value": "3",
                    "displayValue": "Closed Complete"
                },
                {
                    "value": "4",
                    "displayValue": "Closed Incomplete"
                },
                {
                    "value": "7",
                    "displayValue": "Closed Skipped"
                }
            ],
            "hidden": false,
            "internalColumnName": {
                "pm_project_task": "state"
            }
        },
        {
            "label": "Project Phase",
            "name": "phase",
            "editable": false,
            "type": "string",
            "width": 130,
            "hideable": false,
            "cellContextMenu": false,
            "isChoice": true,
            "choices": [{
                    "value": "pre_project",
                    "displayValue": "Pre-Project"
                },
                {
                    "value": "concept_and_initiation",
                    "displayValue": "Concept & Initiation"
                },
                {
                    "value": "execution",
                    "displayValue": "Execution"
                },
                {
                    "value": "project_close",
                    "displayValue": "Project Close"
                }
            ],
            "hidden": false,
            "internalColumnName": {
                "pm_project_task": "phase"
            }
        },
        {
            "label": "Additional assignee list",
            "name": "additional_assignee_list",
            "editable": true,
            "type": "avatar_group",
            "width": 250,
            "hidden": false,
            "cellContextMenu": false,
            "hideable": true,
            "dbColumnName": "additional_assignee_list",
            "internalColumnName": {
                "pm_project_task": "additional_assignee_list"
            }
        },
        {
            "label": "Release",
            "name": "u_release",
            "editable": true,
            "type": "reference",
            "width": 130,
            "hidden": false,
            "hideable": true,
            "cellContextMenu": false,
            "dbColumnName": "u_release",
            "internalColumnName": {
                "pm_project_task": "u_release"
            }
        },
        {
            "label": "Task Region",
            "name": "u_task_region",
            "editable": true,
            "type": "reference",
            "width": 130,
            "hidden": false,
            "hideable": true,
            "cellContextMenu": false,
            "dbColumnName": "u_task_region",
            "internalColumnName": {
                "pm_project_task": "u_task_region"
            }
        },
        {
            "label": "Task Phase",
            "name": "u_task_phase",
            "editable": true,
            "type": "reference",
            "width": 130,
            "hidden": false,
            "hideable": true,
            "cellContextMenu": false,
            "dbColumnName": "u_task_phase",
            "referenceTable": "u_ppm_reference_choices",
            "internalColumnName": {
                "pm_project_task": "u_task_phase"
            }
        }
    ];

    var TABLE_CONFIGS = {
        pm_portfolio: {
            orderBy: 'name',
            parentField: null,
            query: [],
            displaySuffix: '(Portfolio)',
            requiredFields: ['sys_id', 'name', 'description', 'portfolio_manager']
        },
        pm_program: {
            parentField: 'portfolio.sys_id',
            orderBy: 'short_description',
            query: [],
            displaySuffix: '(Program)',
            requiredFields: ['sys_id', 'short_description', 'description', 'start_date', 'end_date', 'state', 'program_manager', 'portfolio']
        },
        pm_project: {
            parentField: 'primary_portfolio.sys_id',
            orderBy: 'short_description',
            query: [],
            displaySuffix: '(Project)',
            requiredFields: ['sys_id', 'short_description', 'description', 'start_date', 'end_date', 'state', 'phase', 'project_manager', 'primary_program', 'primary_portfolio']
        },
        pm_project_task: {
            parentField: 'top_portfolio.sys_id',
            orderBy: 'number',
            query: [],
            displaySuffix: '(Project Task)',
            requiredFields: ['sys_id', 'short_description', 'description', 'start_date', 'end_date', 'assigned_to', 'state', 'additional_assignee_list', 'u_release', 'u_task_region', 'u_task_phase', 'parent']
        }
    };

    function formatDate(dateString) {
        return dateString ? dateString.split(' ')[0] : '';
    }

    function createRecordTemplate(record, tableName) {
        const config = TABLE_CONFIGS[tableName];
        const template = {
            id: record.getValue('sys_id'),
            text: {
                value: record.getValue(tableName === 'pm_portfolio' ? 'name' : 'short_description'),
                displayValue: record.getDisplayValue(tableName === 'pm_portfolio' ? 'name' : 'short_description') +
                    ' ' + config.displaySuffix
            },
            description: {
                value: record.getValue('description'),
                displayValue: record.getDisplayValue('description')
            },
            u_table_name: {
                value: record.getTableName(),
                displayValue: record.getTableName()
            },
            _metadata: {
                tableName: tableName
            },
            parent: null
        };

        // Add table-specific fields
        if (tableName !== 'pm_portfolio') {
            template.startDate = {
                value: record.getValue('start_date'),
                displayValue: formatDate(record.getDisplayValue('start_date'))
            };
            template.endDate = {
                value: record.getValue('end_date'),
                displayValue: formatDate(record.getDisplayValue('end_date'))
            };
            template.duration = (function() {
                    gd = new GlideDuration();
                    gd.setValue(record.getValue('duration'));
                    var durVal = gd.getDayPart() != 0 ? gd.getDayPart() : "0";
					return {
                        value: durVal,
						displayValue: durVal
                    };
                })(),

                template.state = {
                    value: record.getValue('state'),
                    displayValue: record.getDisplayValue('state')
                };
        }

        // Set parent field based on table type
        switch (tableName) {
            case 'pm_program':
                template.parent = record.getValue('portfolio');
                break;
            case 'pm_project':
                template.parent = !record.primary_program.nil() ?
                    record.getValue('primary_program') :
                    record.getValue('primary_portfolio');
                template.phase = {
                    value: record.getValue('phase'),
                    displayValue: record.getDisplayValue('phase')
                };
                break;
            case 'pm_project_task':
                template.parent = record.getValue('parent');
                // Add task-specific fields
                template.assigned_to = {
                    value: record.getValue('assigned_to'),
                    displayValue: record.getDisplayValue('assigned_to')
                };
                template.additional_assignee_list = {
                    value: record.getValue('additional_assignee_list'),
                    displayValue: record.getDisplayValue('additional_assignee_list')
                };
                ['u_release', 'u_task_region', 'u_task_phase'].forEach(field => {
                    template[field] = {
                        value: record.getValue(field),
                        displayValue: record.getDisplayValue(field)
                    };
                });
                break;
        }

        // Set owner field
        template.owner = {
            value: record.getValue(tableName === 'pm_project_task' ? 'assigned_to' :
                tableName === 'pm_project' ? 'project_manager' :
                tableName === 'pm_program' ? 'program_manager' : 'portfolio_manager'),
            displayValue: record.getDisplayValue(tableName === 'pm_project_task' ? 'assigned_to' :
                tableName === 'pm_project' ? 'project_manager' :
                tableName === 'pm_program' ? 'program_manager' : 'portfolio_manager')
        };

        return template;
    }

    function getRelatedRecord(table, portfolio_field, query) {
        var recs = [];
        var gr = new GlideRecordSecure(table);
        gr.addEncodedQuery(query);
        gr.query();
        while (gr.next()) {
            if (!gr[portfolio_field].nil() && recs.indexOf(gr.getValue(portfolio_field)) == -1)
                recs.push(gr.getValue(portfolio_field));
        }
        return recs;
    }

    function queryRecords(tableName, usePagination, firstRow, lastRow) {
        const gr = new GlideRecordSecure(tableName);
        const config = TABLE_CONFIGS[tableName];
        if (config.query.length > 0 && !usePagination) {
            gr.addEncodedQuery(config.query.length > 1 ? config.query.join('^') : config.query);
        }
        if (config.orderBy) {
            gr.orderBy(config.orderBy);
        }
        if (tableName === 'pm_portfolio' && usePagination) {
            gr.chooseWindow(firstRow, lastRow);
        }
        if (tableName == 'pm_project' && TABLE_CONFIGS.pm_program.query.toString().indexOf('5fde787f47ba4e5816b98e87536d432e') > -1) {
            gr.chooseWindow(firstRow, lastRow);
        }
        if (tableName == 'pm_project_task' && TABLE_CONFIGS.pm_program.query.toString().indexOf('5fde787f47ba4e5816b98e87536d432e') > -1) {
            gr.addEncodedQuery('top_task.sys_idIN' + projectIds.join());
        }
        if (config.parentField && portfolioIds.length && usePagination) {
            gr.addEncodedQuery(config.parentField + 'IN' + portfolioIds.join(','));
        }
        //gs.info(tableName + '::' + gr.getEncodedQuery());
        gr.query();
        return gr;
    }

    function processRecords() {
        const page = parseInt(request.body.data.page);
        const filter_obj = Object.keys(request.body.data.query).length === 0 ? [] : request.body.data.query;
        const firstRow = page * ITEMS_PER_PAGE;
        const lastRow = firstRow + ITEMS_PER_PAGE;
        const results = [];
        var usePagination = filter_obj.length == 0;
        filter_obj.forEach(f => {
            const {
                label,
                source,
                values
            } = f;
            switch (label) {
                case 'Portfolio':
                    TABLE_CONFIGS.pm_portfolio.query.push("sys_idIN" + values);
                    TABLE_CONFIGS.pm_program.query.push("portfolio.sys_idIN" + values);
                    TABLE_CONFIGS.pm_project.query.push('primary_portfolio.sys_idIN' + values);
                    TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.sys_idIN' + values);
                    break;
                case 'Program':
                    TABLE_CONFIGS.pm_program.query.push("sys_idIN" + values);
                    var portfolios = getRelatedRecord('pm_program', 'portfolio', "sys_idIN" + values);
                    TABLE_CONFIGS.pm_portfolio.query.push((portfolios.length > 0) ? "sys_idIN" + portfolios : -1);
                    if (portfolios.length > 0) {
                        TABLE_CONFIGS.pm_project.query.push('primary_portfolio.sys_idIN' + portfolios);
                        TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.sys_idIN' + portfolios);
                    }
                    TABLE_CONFIGS.pm_project.query.push('primary_program.sys_idIN' + values);
                    TABLE_CONFIGS.pm_project_task.query.push('top_program.sys_idIN' + values);
                    break;
                case 'Project':
                    TABLE_CONFIGS.pm_project.query.push("sys_idIN" + values);
                    var portfolios = getRelatedRecord('pm_project', 'primary_portfolio', "sys_idIN" + values);
                    TABLE_CONFIGS.pm_portfolio.query.push((portfolios.length > 0) ? "sys_idIN" + portfolios : -1);
                    if (portfolios.length > 0) {
                        TABLE_CONFIGS.pm_project.query.push('primary_portfolio.sys_idIN' + portfolios);
                        TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.sys_idIN' + portfolios);
                    }

                    var programs = getRelatedRecord('pm_project', 'primary_program', "sys_idIN" + values);
                    if (programs.length > 0) {
                        TABLE_CONFIGS.pm_program.query.push("sys_idIN" + programs);
                        TABLE_CONFIGS.pm_project.query.push('primary_program.sys_idIN' + programs);
                        TABLE_CONFIGS.pm_project_task.query.push('top_program.sys_idIN' + programs);
                    }
                    break;
                case 'Portfolio Manager':
                    TABLE_CONFIGS.pm_portfolio.query.push('portfolio_manager.sys_idIN' + values);
                    TABLE_CONFIGS.pm_program.query.push("portfolio.portfolio_manager.sys_idIN" + values);
                    TABLE_CONFIGS.pm_project.query.push('primary_portfolio.portfolio_manager.sys_idIN' + values);
                    TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.portfolio_manager.sys_idIN' + values);
                    break;
                case 'Program Manager':
                    TABLE_CONFIGS.pm_program.query.push('program_manager.sys_idIN' + values);
                    var portfolios = getRelatedRecord('pm_program', 'portfolio', "program_manager.sys_idIN" + values);
                    TABLE_CONFIGS.pm_portfolio.query.push((portfolios.length > 0) ? "sys_idIN" + portfolios : -1);
                    if (portfolios.length > 0) {
                        TABLE_CONFIGS.pm_project.query.push('primary_portfolio.sys_idIN' + portfolios);
                        TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.sys_idIN' + portfolios);
                    }
                    TABLE_CONFIGS.pm_project.query.push('primary_program.program_manager.sys_idIN' + values);
                    TABLE_CONFIGS.pm_project_task.query.push('top_program.program_manager.sys_idIN' + values);
                    break;
                case 'Project Manager':
                    TABLE_CONFIGS.pm_project.query.push('project_manager.sys_idIN' + values);
                    var portfolios = getRelatedRecord('pm_project', 'primary_portfolio', "project_manager.sys_idIN" + values);
                    TABLE_CONFIGS.pm_portfolio.query.push((portfolios.length > 0) ? "sys_idIN" + portfolios : -1);
                    // if (portfolios.length > 0) {
                    //     TABLE_CONFIGS.pm_project.query.push('primary_portfolio.sys_idIN' + portfolios);
                    //     TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.sys_idIN' + portfolios);
                    // }
                    var programs = getRelatedRecord('pm_project', 'primary_program', "project_manager.sys_idIN" + values);
                    TABLE_CONFIGS.pm_program.query.push((programs.length > 0) ? "sys_idIN" + programs : -1);
                    // if (programs.length > 0) {
                    //     TABLE_CONFIGS.pm_project.query.push('primary_program.sys_idIN' + programs);
                    //     TABLE_CONFIGS.pm_project_task.query.push('top_program.sys_idIN' + programs);
                    // }
                    TABLE_CONFIGS.pm_project_task.query.push('top_task.ref_pm_project.project_manager.sys_idIN' + values);

                    break;
                case 'Project Phase(Should be used in conjunction with other filters)':
                    TABLE_CONFIGS.pm_project.query.push('phaseIN' + values);
                    var portfolios = getRelatedRecord('pm_project', 'primary_portfolio', "phaseIN" + values);
                    TABLE_CONFIGS.pm_portfolio.query.push((portfolios.length > 0) ? "sys_idIN" + portfolios : -1);
                    // if (portfolios.length > 0) {
                    //     TABLE_CONFIGS.pm_project.query.push('primary_portfolio.sys_idIN' + portfolios);
                    //     TABLE_CONFIGS.pm_project_task.query.push('top_portfolio.sys_idIN' + portfolios);
                    // }
                    var programs = getRelatedRecord('pm_project', 'primary_program', "phaseIN" + values);
                    TABLE_CONFIGS.pm_program.query.push((programs.length > 0) ? "sys_idIN" + programs : -1);
                    // if (programs.length > 0) {
                    //     TABLE_CONFIGS.pm_project.query.push('primary_program.sys_idIN' + programs);
                    //     TABLE_CONFIGS.pm_project_task.query.push('top_program.sys_idIN' + programs);
                    // }
                    TABLE_CONFIGS.pm_project_task.query.push('top_task.ref_pm_project.phaseIN' + values);
                    usePagination = false;
                    break;
                case 'State':
                    TABLE_CONFIGS.pm_project_task.query.push("stateIN" + values);
                    break;
            }
        });
        var tables = ['pm_portfolio', 'pm_program', 'pm_project', 'pm_project_task']
        for (var i = 0; i < tables.length; i++) {
            //['pm_portfolio','pm_program'].forEach(f => {
            var f = tables[i];
            let gr = queryRecords(f, usePagination, firstRow, lastRow);
            if (f == 'pm_portfolio' && usePagination)
                portfolioCount = gr.getRowCount();
            if (f == 'pm_project' && TABLE_CONFIGS.pm_program.query.toString().indexOf('5fde787f47ba4e5816b98e87536d432e') > -1) {
                portfolioCount = gr.getRowCount();
            }

            while (gr.next()) {
                if (f == 'pm_portfolio') {
                    portfolioIds.push(gr.getValue('sys_id'));
                }
                if (f == 'pm_project' && TABLE_CONFIGS.pm_program.query.toString().indexOf('5fde787f47ba4e5816b98e87536d432e') > -1) {
                    projectIds.push(gr.getValue('sys_id'));
                }

                results.push(createRecordTemplate(gr, f));
            }
        }

        return results;
    }

    // Main execution
    try {
        const ganttData = processRecords();
        response.setBody({
            gantt_data: ganttData,
            column_conf: COLUMN_DATA,
            count: portfolioCount,
            table_conf: TABLE_CONFIGS
        });
        logger.push(JSON.stringify(TABLE_CONFIGS));
       // gs.info(logger.join());
    } catch (error) {
        gs.error('Error in GetProjectTaskChronology: ' + error);
        response.setStatus(500);
    }

})(request, response);
